    constructor(C _c) { c = _c; }

    function run(address newOwner) public payable {
        require(newOwner != address(this));
        address before = c.owner();

        // Non-owner (this test contract is not owner unless owner == address(this))
        bool revertedNonOwner;
        if (before != address(this)) {
