    function run(address newOwner, address target) public payable {
        require(newOwner != address(this));

        // Initially the test contract is the owner (it deployed c); hand over ownership.
        bool ok1 = c.setOwner(newOwner);

        bool reverted;
        address before;
        if (ok1 && newOwner != address(this)) {
            before = c.owner();
            try c.setOwner(target) { reverted = false; } catch { reverted = true; }
        }

        bool ok2;
        address afterOwner;
        if (ok1 && newOwner == address(this)) {
            ok2 = c.setOwner(target);
            afterOwner = c.owner();
        }

        assert(
            ok1
            && (newOwner != address(this) ? (reverted && c.owner() == before) : (ok2 && afterOwner == target))
        );
    }
    receive() external payable {}
}

