contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a) public {
        require(a != address(this));
        c.setOwner(a);
        bool reverted;
        try c.setOwner(a) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == a);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(msg.sender == address(this));
        require(c.owner() == address(this));
        bool ok = c.setOwner(newOwner);
        assert(ok && c.owner() == newOwner);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount <= address(c).balance + 1 ether);
        uint balBefore = address(c).balance;
        bool ok = c.setOwner{value: amount}(newOwner);
        assert(ok && address(c).balance == balBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address attacker, address attemptedOwner) public {
        require(newOwner != address(this));
        c.setOwner(newOwner);
        address ownerAfterTransfer = c.owner();
        bool reverted;
        try c.setOwner(attemptedOwner) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.owner() == ownerAfterTransfer && ownerAfterTransfer == newOwner);
    }
    receive() external payable {}
}
